update public.preguntas set
    explicacion = v.explicacion::text,
    norma = v.norma::text
from (values
('cap-4f84375b06e6', 'El sector del transporte de mercancías con vehículos ligeros en España se caracteriza por tener muchas empresas pequeñas, a menudo autónomos o microempresas. Esto significa que hay un alto nivel de atomización empresarial, es decir, el sector está muy fragmentado. La opción de alto nivel de concentración empresarial es incorrecta porque la concentración se da cuando pocas empresas grandes dominan el mercado, lo cual no ocurre en este segmento.', NULL),
('cap-4f9791fa4b98', 'El diseño del espacio y los medios de trabajo debe considerar las medidas del cuerpo humano para asegurar la ergonomía. También es fundamental tener en cuenta la altura a la que se realiza el trabajo y el asiento utilizado, ya que influyen directamente en la postura y la comodidad del conductor. Por lo tanto, todos estos factores son importantes para una concepción adecuada del puesto de trabajo.', NULL),
('cap-4fef24d2143b', 'La energía cinética es la energía que tiene un cuerpo en movimiento. Depende directamente de la masa del vehículo y del cuadrado de su velocidad. Por eso, un pequeño aumento de la velocidad tiene un gran impacto en la energía cinética. Multiplicar la mitad de la velocidad por el cuadrado de la masa es incorrecto porque la velocidad tiene un impacto mucho mayor que la masa en la energía cinética.', NULL),
('cap-4ffe5e6072ae', 'Las autorizaciones CEMT de carga general se expiden en un número limitado para controlar el acceso al mercado de transporte internacional. Esto asegura un equilibrio entre la oferta y la demanda de servicios de transporte. Las autorizaciones para mudanzas no están sujetas a esta limitación numérica. Pensar que ninguna autorización CEMT está limitada es un error, ya que las de carga general sí lo están.', NULL),
('cap-5012aa395588', 'La resistencia de la pendiente es una de las principales fuerzas que se oponen al movimiento de un vehículo, ya que el motor debe vencer la fuerza de la gravedad para subir una cuesta. Las resistencias del árbol de transmisión, del grupo cónico diferencial y del volante de inercia son resistencias internas del propio vehículo, no externas al movimiento.', NULL),
('cap-501ed64b61b5', 'Una sobrecarga en el eje trasero concentra todo el peso extra en esa parte del vehículo, lo que fuerza la suspensión trasera más allá de sus límites de diseño. Esto provoca que la suspensión trabaje de forma ineficiente y transmita directamente los impactos al chasis, pudiendo dañarlo. La dureza en la dirección del vehículo es un síntoma de sobrecarga en el eje delantero, no en el trasero.', NULL),
('cap-5020dcb9c954', 'El tacógrafo digital adapta su funcionamiento según la tarjeta que se inserte, ya sea de conductor, de empresa, de centro de ensayo o de control. Cada tipo de tarjeta activa funciones específicas del tacógrafo, como el registro de la actividad del conductor o la descarga de datos por parte de la empresa. Por ejemplo, al insertar una tarjeta de conductor, el tacógrafo registra automáticamente los tiempos de conducción y descanso. La afirmación de que no cambia el modo de funcionamiento es incorrecta, ya que el tacógrafo está diseñado para interactuar de forma diferente con cada tipo de tarjeta.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado II, 3 (3821/85)'),
('cap-504eb9629415', 'Las enfermedades profesionales son aquellas que se contraen por realizar un trabajo específico y que están recogidas en un listado oficial. No basta con que sea por cualquier trabajo o por una profesión de riesgo, sino que debe estar tipificada en el cuadro de enfermedades profesionales. La ley exige que la enfermedad esté en ese cuadro y que se haya producido por las actividades y elementos que se indican en él. La opción que dice que son correctas a la vez dos definiciones es incorrecta porque solo una de ellas es la definición legal exacta.', 'RD Legislativo 8/2015 Art. 157;Art. 316'),
('cap-505711e258a7', 'A mayor velocidad, el camión debe "abrirse paso" a través de una mayor cantidad de aire en el mismo periodo de tiempo. Esto se debe a que el vehículo recorre una distancia mayor en el mismo intervalo, encontrándose con más partículas de aire en su camino. Por lo tanto, la resistencia aerodinámica aumenta significativamente con la velocidad, lo que implica un mayor esfuerzo para el motor y un mayor consumo de combustible. No se trata de la misma cantidad de aire, ya que el volumen de aire desplazado por unidad de tiempo es directamente proporcional a la velocidad del vehículo.', NULL),
('cap-50660a7e6522', 'Las hojas de registro o discos-diagrama deben llevar impreso el nombre, apellidos y domicilio o marca del fabricante. Esto es un requisito para identificar al responsable de la fabricación del disco. La circunferencia efectiva de los neumáticos no se imprime en el disco, es un dato del vehículo. El nombre del instalador o taller autorizado tampoco se imprime en el disco, aunque es importante para el mantenimiento del tacógrafo.', 'Reglamento Comunitario (UE) 165/2014 Anexo I, apartado IV, c'),
('cap-508d119fd668', 'Los transportistas tienen la obligación de remitir a las autoridades españolas la información de los pasajeros antes de la salida del medio de transporte, según la Ley Orgánica 4/2000 Art. 66.1. Esto es para combatir la inmigración ilegal y garantizar la seguridad pública en rutas de fuera del Espacio Schengen. La opción que indica un plazo de quince días es incorrecta, ya que la información se requiere antes de que el transporte inicie su ruta.', 'Ley Orgánica 4/2000 Art. 66.1'),
('cap-509398c5d41e', 'La calidad es el factor más influyente porque un servicio de transporte de calidad genera confianza y satisfacción en el cliente, lo que se traduce en una percepción positiva de la marca. Un servicio deficiente, por el contrario, daña la reputación de la empresa. Aunque la experiencia en el mercado puede ser un indicio, no garantiza la calidad actual del servicio. El precio es importante, pero un precio bajo sin calidad puede ser contraproducente para la imagen a largo plazo.', NULL),
('cap-50fb29ea7cb4', 'La conducción preventiva busca que el conductor se anticipe a los riesgos del tráfico para evitar accidentes. Se trata de prever lo que puede ocurrir en la vía y actuar con tiempo para mantener la seguridad. No se centra en las averías mecánicas, que son un aspecto del mantenimiento del vehículo, no de la técnica de conducción preventiva. Tampoco tiene que ver con el régimen de revoluciones o el uso de marchas altas, que son técnicas de conducción eficiente, no preventiva.', NULL),
('cap-5106e86eac72', 'Debajo de las letras de identificación, el Acuerdo ATP Anejo I, Apéndice 4 establece que se debe indicar la fecha de expiración del certificado, mostrando el mes y el año. Esto es crucial para saber hasta cuándo es válido el equipo para el transporte internacional de mercancías perecederas. No se indica la fecha de expedición del certificado, ya que lo relevante es la validez actual, no cuándo se emitió. Tampoco se muestra la fecha de la última o próxima inspección, sino la caducidad del certificado.', 'Acuerdo ATP Anejo I, Apéndice 4'),
('cap-513ee7593813', 'El índice de mortalidad mide la gravedad de los accidentes, relacionando directamente el número de personas que pierden la vida con la distancia total recorrida por los vehículos. Esto permite evaluar el riesgo de fallecimiento por cada kilómetro que se circula. No se refiere al número de accidentes con víctimas, ya que eso sería un índice de accidentalidad, no de mortalidad. Tampoco compara víctimas y fallecidos, sino que se centra solo en los fallecidos.', NULL),
('cap-515da92531aa', 'Las hemorragias y asfixias son las causas más frecuentes de muerte en la primera hora tras un accidente porque comprometen rápidamente funciones vitales como la respiración y la circulación sanguínea. Un aplastamiento puede ser mortal, pero las hemorragias y asfixias son más comunes en esa primera hora. Los infartos no son la causa principal de muerte en la hora siguiente a un accidente, aunque el estrés del suceso pueda desencadenarlos. Las fracturas de huesos, por sí solas, rara vez son mortales en la primera hora, a menos que causen hemorragias internas graves.', NULL),
('cap-51671a053fb3', 'La cortesía, la accesibilidad y el lenguaje claro son fundamentales para una buena relación con el cliente. Un trato cortés genera confianza y profesionalidad. Ser accesible facilita la comunicación y la resolución de problemas. Utilizar un lenguaje claro evita malentendidos y asegura que el cliente comprenda la información.', NULL),
('cap-519940b30233', 'Los transportes de mercancías de carácter privado particular no necesitan ninguna autorización administrativa. Se realizan con vehículos propios y para necesidades propias de la empresa o persona, sin que el transporte sea la actividad principal. La autorización de transporte privado complementario es para empresas que, aunque no se dedican al transporte, lo necesitan para su actividad principal, como una tienda que reparte sus productos.', 'RD 1211/1990 Art. 41'),
('cap-51a2e2852086', 'La potencia de un motor se mide en kilovatios, que es la unidad de medida estándar en el Sistema Internacional para la potencia. Aunque tradicionalmente se usaban los caballos de vapor, los kilovatios son la medida oficial y técnica. Los caballos fiscales no miden la potencia real del motor, sino que son un valor para fines tributarios.', NULL),
('cap-51a987693794', 'El sistema ESP (Programa Electrónico de Estabilidad) está diseñado para ayudar al conductor a mantener el control del vehículo, especialmente en situaciones de riesgo como curvas cerradas o superficies deslizantes. Actúa frenando individualmente las ruedas y ajustando la potencia del motor para corregir la trayectoria y evitar derrapes. Por lo tanto, mejora activamente cómo el vehículo sigue la trayectoria deseada por el conductor. No es un sistema de control de presión de ruedas, eso es el TPMS.', NULL),
('cap-51b40c725774', 'El Reglamento Comunitario (CE) 561/2006 Art. 10.1 prohíbe expresamente que las empresas remuneren a los conductores en función de la carga transportada si esto pudiera comprometer la seguridad en carretera o fomentar infracciones. La seguridad es prioritaria y no debe verse afectada por incentivos económicos. La opción que indica que no se puede en ningún caso es incorrecta, ya que la prohibición solo aplica si se compromete la seguridad.', 'Reglamento Comunitario (CE) 561/2006 Art. 10.1'),
('cap-51ba075e8379', 'El "transroulage" es el término específico para el sistema de transporte intermodal que permite que los vehículos, como camiones o remolques, suban y bajen de un barco por sus propios medios o remolcados. Esta técnica es fundamental para agilizar las operaciones de carga y descarga en los puertos. El "ferroutage" se refiere al transporte combinado carretera-ferrocarril, no al marítimo. "Translage" y "Barroulage" no son términos reconocidos en el transporte intermodal.', NULL),
('cap-51f50f9a5eb6', 'En una sociedad anónima, el capital está dividido en acciones, y los socios son precisamente quienes poseen esas acciones. La afirmación de que no puede tener un único socio es incorrecta, ya que existe la figura de la sociedad anónima unipersonal. Los administradores no tienen privilegio de anonimato; sus datos son públicos.', 'RD Legislativo 1/2010 Art. 1.3'),
('cap-52009af61061', 'Los centros de transporte y logística de mercancías son lugares que agrupan servicios e instalaciones para facilitar el transporte, la logística y la distribución de mercancías, incluyendo actividades preparatorias y complementarias. No se limitan solo al almacenamiento o a la recepción de mercancías, sino que abarcan un conjunto más amplio de funciones. Tampoco son solo instalaciones públicas para contratar transportes, ya que su gestión puede ser pública o privada y su objetivo es más amplio que la mera contratación. La Ley 16/1987 Art. 127 lo define claramente.', 'Ley 16/1987 Art. 127'),
('cap-5203bdeaa768', 'La carencia de discos-diagrama para el tacógrafo no es motivo de inmovilización del vehículo, aunque sí es una infracción sancionable. La Ley 16/1987 Art. 143.4 establece los supuestos de inmovilización, y la falta de discos no está entre ellos. La manipulación del tacógrafo, la utilización de una tarjeta falsificada o la obstrucción a la inspección son infracciones graves que sí pueden llevar a la inmovilización del vehículo.', 'Ley 16/1987 Art. 143.4'),
('cap-524378f4cbd5', 'Con viento, es fundamental reducir la velocidad para mantener el control del vehículo, ya que el viento lateral puede desplazarlo. Sujetar el volante con firmeza es crucial para contrarrestar los empujes del viento y evitar desviaciones inesperadas. Además, hay que prestar especial atención al pasar de zonas resguardadas a zonas expuestas, como al salir de un túnel o al cruzar un puente, porque el cambio repentino de la fuerza del viento puede desestabilizar el camión.', NULL),
('cap-526979411f76', 'Para el transporte privado complementario, la necesidad de autorización depende de la Masa Máxima Autorizada del vehículo. Según la OM FOM/734/2007 Art. 3, los transportes privados complementarios en vehículos de hasta 3,5 toneladas de MMA están exentos de autorización. Por encima de ese peso, sí se necesita. La idea de que no se necesita nunca es incorrecta, ya que la exención tiene un límite de peso.', 'OM FOM/734/2007 Art. 3'),
('cap-52803d3d7987', 'La somnolencia se manifiesta de diversas formas, y todas las opciones presentadas son indicadores claros. Las dificultades para enfocar la vista, la pérdida de concentración y los bostezos repetidos son síntomas inequívocos de que el cansancio está afectando tu capacidad para conducir de forma segura. Es crucial reconocer cualquiera de estas señales para tomar un descanso antes de que la situación se vuelva peligrosa.', NULL),
('cap-528d7a9a1694', 'Un asiento mal diseñado no absorbe correctamente las vibraciones y golpes, transmitiendo directamente los impactos a la columna vertebral del conductor. Esto puede provocar lesiones graves o crónicas en la espalda. Las manos, los pies o la cabeza no son el punto principal de transmisión de impactos en este caso, aunque puedan verse afectados secundariamente.', NULL),
('cap-52ad72168d8a', 'La autorización CEMT es para transportes internacionales entre países miembros, no para operaciones de cabotaje. El cabotaje es el transporte de mercancías dentro de un mismo país por un transportista no residente, y la autorización CEMT no lo permite. La idea de que se permite una expedición o un número limitado de expediciones en el estado de destino es incorrecta, ya que la CEMT no regula el cabotaje.', NULL),
('cap-52aff8995b64', 'Una inmovilización por exceso de conducción diaria, como 14 horas, es una infracción grave que no se levanta con una simple pausa. La Ley 16/1987 Art. 143.4 establece que la inmovilización se mantiene hasta que se eliminen los motivos de la infracción. Realizar una pausa de 45 minutos no subsana el exceso de conducción ya realizado. La inmovilización no depende de la nacionalidad del vehículo, sino de la infracción cometida.', 'Ley 16/1987 Art. 143.4'),
('cap-52b74143c0cf', 'Cada cuaderno TIR está diseñado para un único viaje. Esto significa que, una vez utilizado para un transporte, ya no es válido para otro, incluso si aún está dentro de su periodo de validez. El Convenio TIR Art. 17 establece claramente esta limitación. La idea de que sirve para varios viajes o para todos los que se realicen dentro de su validez es incorrecta y un error común.', 'Convenio TIR Art. 17'),
('cap-52dfa803c43f', 'La tarjeta de conductor para tacógrafo digital tiene un plazo de validez de cinco años, tal como establece la OM FOM/1190/2005 Art. 5. Es importante recordar este periodo para evitar problemas con la normativa. La validez no está ligada a la del permiso de conducir, son documentos distintos con plazos independientes.', 'OM FOM/1190/2005 Art. 5'),
('cap-5315015e83b7', 'Los tacógrafos analógicos deben registrar los cortes de alimentación cuando su funcionamiento depende de señales eléctricas que le llegan desde el sensor de distancia y velocidad. Esto es crucial para asegurar la integridad de los datos de registro. Si el tacógrafo no depende de esas señales eléctricas para su funcionamiento, no tiene por qué registrar los cortes de alimentación. No es una característica exclusiva de los modelos más modernos, sino de su tipo de conexión.', NULL),
('cap-531f702b5f16', 'La energía cinética de un vehículo en movimiento aumenta significativamente con la velocidad. A mayor velocidad, el vehículo acumula más energía, lo que implica que necesitará más distancia para detenerse y el impacto en caso de colisión será mucho más grave. Pensar que la energía es independiente de la velocidad es un error, ya que la velocidad es el factor que más influye en la energía que lleva el vehículo.', NULL),
('cap-5324ef4234d8', 'Circular a una velocidad media más baja reduce la probabilidad de accidentes, lo que aumenta la seguridad. Además, al ir más despacio, el motor trabaja de forma más eficiente, lo que se traduce en un menor consumo de combustible y, por tanto, en menos emisiones contaminantes. La opción de aumentar el coeficiente aerodinámico es incorrecta, ya que este coeficiente se ve afectado por la forma del vehículo y no por la velocidad a la que circula.', NULL),
('cap-533845011519', 'La temperatura idónea es aquella que permite al conductor mantener un confort térmico adecuado para realizar su trabajo sin distracciones ni fatiga por el calor o el frío. No se trata de una temperatura fija, sino de un rango que favorece la concentración y el bienestar. Pasar calor o buscar temperaturas extremas, ya sean muy frías o muy cálidas, son condiciones que pueden afectar negativamente el rendimiento y la seguridad al volante.', NULL),
('cap-5339702f8124', 'Los retardadores son dispositivos auxiliares de frenado que se integran en la cadena cinemática del vehículo, normalmente en la caja de cambios o el árbol de transmisión. Su funcionamiento se basa en la resistencia que opone un fluido, generalmente aceite, al movimiento de un rotor dentro de una carcasa. Esta resistencia genera un par de frenado que ayuda a reducir la velocidad del vehículo de forma continua y sin desgaste de los frenos de servicio. No son neumáticos, ya que estos se usan para los frenos de servicio o la suspensión, ni mecánicos en el sentido de fricción directa, ni eléctricos como los frenos electromagnéticos.', NULL),
('cap-534d9aa16af5', 'Los estatutos de una sociedad de responsabilidad limitada tienen la flexibilidad de establecer un método de convocatoria individual y escrito. Lo importante es que este procedimiento garantice que todos los socios reciban el aviso de la junta. Aunque la ley prevé la publicación en el Boletín Oficial del Registro Mercantil o en la web de la sociedad, el RD Legislativo 1/2010 Art. 173 permite que los estatutos fijen otro sistema. La opción de publicar solo en el Boletín Oficial del Registro Mercantil o en la web de la sociedad no es la única vía, ya que los estatutos pueden modificarlo.', 'RD Legislativo 1/2010 Art. 173'),
('cap-5350a5fbf055', 'La declaración amistosa de accidente es una herramienta para agilizar los trámites con el seguro, no para reducir los atascos. Para que la declaración amistosa sea válida, es imprescindible tener suscrito el seguro de responsabilidad civil obligatorio. Según la Ley 50/1980 Art. 16, el plazo máximo para comunicar un siniestro al asegurador es de siete días, no de veinte.', 'Ley 50/1980 Art. 16'),
('cap-539c2604293b', 'Cuanto más peso transporta un vehículo, más energía necesita para moverse, lo que se traduce directamente en un mayor consumo de combustible. Por eso, no cargar el vehículo en exceso es la medida más efectiva para ahorrar. Bajar pendientes en punto muerto o con el embrague pisado es peligroso y no ahorra combustible, ya que el motor sigue girando sin retención. Una presión de inflado inferior a la recomendada aumenta la resistencia a la rodadura y, por tanto, el consumo, además de ser inseguro.', NULL),
('cap-53b26457fd62', 'Existen extintores de CO2, que son muy eficaces para fuegos eléctricos y líquidos inflamables. También se utilizan extintores de agua pulverizada, adecuados para fuegos de tipo A (materiales sólidos). Finalmente, los extintores de polvo químico son muy versátiles y se usan en una amplia gama de fuegos. Por lo tanto, todas las opciones mencionadas son tipos de extintores que existen.', NULL),
('cap-53b758659d79', 'El ralentizador eléctrico es un sistema de frenado auxiliar que se usa para mantener la velocidad del vehículo en descensos prolongados o para reducirla sin usar los frenos de servicio. Su función principal es evitar el sobrecalentamiento de los frenos de servicio, que es lo que provoca el "fading" o pérdida de eficacia. Al usar el ralentizador, se reduce la necesidad de pisar el pedal de freno, conservando así su capacidad de frenado para cuando realmente se necesite. Aumentar la energía cinética del vehículo es incorrecto, ya que el ralentizador precisamente la disipa para frenar.', NULL),
('cap-53c1ff572248', 'La fuerza de frenado es la que se opone al movimiento del camión para detenerlo o reducir su velocidad, por lo que interviene directamente en su movimiento. Las otras opciones como la fuerza mayor, la fuerza menor o la fuerza nula no son fuerzas físicas que actúen sobre el vehículo en movimiento. La fuerza mayor es un concepto legal, no una fuerza física que intervenga en el movimiento de un camión.', NULL),
('cap-53f2e8d2264c', 'La autorización multilateral permite transportar mercancías entre varios países, no solo entre dos. Es la que necesitas para operar en más de un país. La autorización bilateral, en cambio, solo permite el transporte entre dos países específicos. La autorización triangular no existe como tal en el transporte internacional de mercancías.', NULL),
('cap-53f8ce1ad9a3', 'El corrector de frenada es un elemento de seguridad que distribuye la fuerza de frenado entre los ejes para evitar bloqueos, pero no tiene ninguna influencia directa en el consumo de combustible. Guardar una distancia de seguridad adecuada, conducir con anticipación y con tranquilidad sí contribuyen al ahorro porque permiten una conducción más fluida, con menos aceleraciones y frenadas bruscas, que son las que disparan el consumo.', NULL),
('cap-543e007720f1', 'Debes comunicar el siniestro a la aseguradora en un plazo máximo de siete días desde que lo conoces. Así lo establece la Ley 50/1980 Art. 16, que busca una comunicación rápida para la gestión del incidente. Si no lo haces, la aseguradora podría reclamarte los daños y perjuicios que le causes por esa falta de aviso. Plazos como catorce, quince o treinta días no son correctos según la normativa general.', 'Ley 50/1980 Art. 16'),
('cap-544a7cff7e87', 'La inmovilización de un vehículo se puede hacer en el lugar donde se detecta la infracción o en el punto más cercano que sea seguro y adecuado para ello. Esto lo establece la Ley 16/1987 Art. 143.4, que busca garantizar la seguridad y la correcta aplicación de la medida. No se limita a un taller o a un área de servicio, ni tampoco exclusivamente al punto exacto de la infracción si no es seguro.', 'Ley 16/1987 Art. 143.4'),
('cap-54647b1b6f57', 'Los clientes valoran la fiabilidad del servicio, es decir, que el transporte llegue a tiempo y en buenas condiciones. También es importante la competencia, que se refiere a la capacidad de la empresa para resolver problemas y ofrecer soluciones. La empatía, que es la capacidad de entender y atender las necesidades del cliente, también influye en la percepción de calidad. Por lo tanto, todos estos factores son importantes para la valoración del servicio.', NULL),
('cap-5471d158baa9', 'Para un masaje cardiaco eficaz, se usa la parte posterior de la palma de una mano, que es la zona más fuerte y con mayor superficie de contacto, para aplicar la fuerza necesaria. La otra mano se coloca encima para aumentar la presión y asegurar que la fuerza se transmite de forma uniforme. Es fundamental mantener los brazos rectos y perpendiculares al pecho del herido para que el peso del cuerpo ayude a la compresión y se evite la fatiga, garantizando la profundidad adecuada en cada pulsación. Cruzar los brazos o usar la parte anterior de la palma no permite aplicar la fuerza de manera efectiva ni mantener la postura correcta.', NULL),
('cap-548d9adca59b', 'La revisión periódica del tacógrafo, tanto analógico como digital, debe realizarse cada dos años. Esta comprobación asegura que el aparato sigue funcionando correctamente y registrando los datos de forma precisa, lo cual es fundamental para el control de los tiempos de conducción y descanso. Realizarla cada año o cada seis meses no es lo que exige la normativa, y cada tres años es un periodo demasiado largo que no garantiza la fiabilidad del tacógrafo.', 'Reglamento Comunitario (UE) 165/2014 Anexo I, apartado VI, 3 y Anexo IB, apartado VI, 4 (3821/85)'),
('cap-54a3f9bf3045', 'La responsabilidad de verificar la documentación de los viajeros recae en el transportista. El incumplimiento de esta obligación se considera una infracción grave y la sanción económica se aplica por cada persona que no cumpla los requisitos. La multa de 5.000 a 10.000 euros por cada viajero transportado es la que corresponde a este tipo de infracción. Las opciones que establecen una cantidad fija para todos los viajeros son incorrectas porque la sanción se individualiza.', NULL),
('cap-54c649395e10', 'Al planificar una ruta, el conductor debe asegurarse de no superar los tiempos máximos de conducción para cumplir con la normativa. Esto es fundamental para la seguridad vial y para evitar sanciones. La opción de no superar los tiempos de descanso es incorrecta porque, aunque los descansos son importantes, la pregunta se centra en la planificación de la ruta y la conducción. Las opciones que permiten superar los tiempos de conducción o los períodos semanales en un porcentaje son incorrectas, ya que la normativa no contempla esas tolerancias para los límites máximos.', 'Reglamento Comunitario (CE) 561/2006 Art. 10'),
('cap-54e2645e9c5a', 'En el tacógrafo analógico, el conductor debe seleccionar manualmente la actividad que está realizando (conducción, otros trabajos, disponibilidad o descanso) para que el aparato la registre correctamente. Si no se selecciona, el tacógrafo no puede diferenciar entre las distintas actividades. La opción que indica que el registro se hace solamente cuando el vehículo se mueve es incorrecta, ya que el tacógrafo también registra otros tiempos de actividad y descanso con el vehículo parado.', 'Reglamento Comunitario (UE) 165/2014 Anexo I, apartado III, 4 y Anexo IB, apartado III.12.4 (3821/85)'),
('cap-54fc149693dd', 'Para reducir el consumo de carburante hay que optimizar la conducción en su conjunto. Esto incluye un uso eficiente del motor, aprovechando su par y potencia de forma adecuada. También es crucial un buen manejo de la caja de velocidades para mantener el motor en su rango óptimo de revoluciones. Además, un uso anticipatorio y suave del sistema de freno, evitando frenadas bruscas, contribuye a la eficiencia general. No es suficiente centrarse solo en el motor, la caja de velocidades o el freno de forma aislada, ya que todos los elementos interactúan en el consumo.', NULL),
('cap-55080011dcdb', 'Sí se puede conducir sin la tarjeta personal de conductor en ciertos casos. El Reglamento Comunitario (UE) 165/2014 Art. 29.5 establece que, si la tarjeta se ha deteriorado, funciona mal, se ha extraviado o ha sido robada, el conductor puede seguir conduciendo sin ella durante un máximo de quince días naturales. Esto es para permitir que el conductor solicite una nueva tarjeta y la reciba. La opción que dice que no se puede conducir en ningún caso es incorrecta, ya que la normativa prevé estas excepciones.', 'Reglamento Comunitario (UE) 165/2014 Art. 29.5'),
('cap-5512b2211825', 'La aerodinámica influye directamente en la resistencia al avance del vehículo, especialmente a velocidades altas, lo que aumenta el consumo. Un buen mantenimiento asegura que todos los sistemas funcionen de manera eficiente, evitando pérdidas de rendimiento y un gasto excesivo de combustible. La presión de los neumáticos también es crucial, ya que una presión incorrecta aumenta la resistencia a la rodadura y, por tanto, el consumo. El motor de arranque y el ralentizador no tienen un impacto directo en el consumo habitual del vehículo.', NULL),
('cap-5514f46f5bbf', 'Los accidentes laborales de tráfico son los que ocurren al ir o volver del trabajo, que se llaman "in itinere", o los que suceden durante el horario laboral mientras se realiza una tarea encomendada por la empresa, que son los "en misión". La opción que dice que ningún accidente de tráfico puede ser laboral es incorrecta, ya que muchos accidentes de tráfico están directamente relacionados con la actividad profesional.', NULL),
('cap-554b908a49c4', 'El transporte de animales vivos entre granjas y mercados locales está exento del uso del tacógrafo. Esta exención se aplica siempre que la distancia en línea recta entre el origen y el destino no supere los 100 kilómetros, tal como establece el RD 640/2007 Art. 2.h. La opción que indica que siempre está obligado al uso del tacógrafo es incorrecta, ya que existen exenciones específicas para este tipo de transporte. Tampoco es correcto que la exención sea siempre, pues está condicionada a la distancia.', 'RD 640/2007 Art. 2.h'),
('cap-55851983d4f9', 'La velocidad se registra en la zona más exterior del anverso del disco-diagrama. Es la parte del disco donde el estilete del tacógrafo marca continuamente la velocidad a la que se mueve el vehículo. La zona más interior del anverso se utiliza para registrar los tiempos de actividad del conductor, no la velocidad.', 'Reglamento Comunitario (UE) 165/2014 Anexo I, apartado III, c'),
('cap-5598f54a6b35', 'La infracción por carencia significativa de datos en el tacógrafo se produce cuando la información registrada es tan incompleta que impide conocer el kilometraje total recorrido. No se trata de un porcentaje específico de kilómetros faltantes, sino de la imposibilidad de determinar el total. Los porcentajes de kilómetros faltantes no son el criterio para esta infracción.', NULL),
('cap-55b1dfe55f53', 'Es fundamental revisar la fecha de caducidad de los extintores para asegurar que funcionen correctamente en caso de incendio. También hay que comprobar el estado del botiquín para garantizar que contiene todo lo necesario y que los productos no están caducados. Los martillos rompecristales deben estar accesibles y en buen estado para poder utilizarlos en una emergencia. Por lo tanto, todas las opciones son comprobaciones necesarias.', NULL),
('cap-55c3ae25a113', 'La ergonomía es una disciplina que busca adaptar el trabajo al ser humano. Para lograrlo, necesita conocimientos de anatomía para entender la estructura del cuerpo, de fisiología para comprender cómo funciona, y de psicología para considerar los aspectos mentales y cognitivos. Por lo tanto, todas estas ciencias son fundamentales y complementarias para la ergonomía.', NULL),
('cap-55dfd5eccb57', 'El fabricante del vehículo es quien diseña y produce el motor, por lo que es el único que conoce con exactitud los valores máximos de potencia que puede desarrollar. Estos datos son fundamentales para la homologación y ficha técnica del vehículo. El vendedor del vehículo simplemente comercializa el producto, no lo diseña.', NULL),
('cap-55efcef7cbca', 'La posición correcta de los brazos al volante es ligeramente flexionada, lo que permite un mayor control y reacción. Si los brazos no están flexionados, se pierde agilidad y capacidad de maniobra. Agarrar el volante con fuerza o tener los brazos tensos son errores que reducen la sensibilidad y aumentan la fatiga.', NULL),
('cap-55fdfa50952b', 'La rigidez torsional de la carrocería es crucial porque determina la resistencia del chasis a retorcerse bajo las fuerzas dinámicas, lo que impacta directamente en cómo se comporta el vehículo en curvas o ante irregularidades del terreno. Una mayor rigidez torsional significa que la carrocería se deforma menos, manteniendo la geometría de la suspensión más estable y mejorando la adherencia de los neumáticos. Esto se traduce en una mayor estabilidad y seguridad, especialmente en vehículos de mercancías que transportan cargas pesadas. La masa neta que se puede levantar no tiene relación directa con la estabilidad dinámica del vehículo en carretera.', NULL),
('cap-56159aa0b22d', 'Para utilizar el régimen de tránsito externo de la Unión, el operador debe constituir una garantía que asegure el pago de la deuda aduanera. Esto se establece en el Reglamento Comunitario (UE) 952/2013 Art. 233, que indica la obligación de asegurar el pago de los derechos de importación o exportación. No se trata de pagar un porcentaje de la deuda por adelantado, sino de tener una garantía que cubra el importe total en caso de que surja la deuda. Las opciones de pagar previamente un porcentaje de la deuda aduanera son incorrectas porque el sistema se basa en una garantía, no en un pago anticipado parcial.', 'Reglamento Comunitario (UE) 952/2013 Art. 233'),
('cap-56260a9c1d3b', 'El Reglamento Comunitario (CE) 561/2006 Art. 8.6 permite tomar un descanso semanal reducido de al menos 24 horas en un periodo de dos semanas consecutivas. En este caso, el conductor ha tomado un descanso semanal reducido de 30 horas, que es legal. La clave es que la reducción de 15 horas (45 - 30) debe compensarse con un descanso equivalente antes de finalizar la tercera semana siguiente. La opción que indica que siempre hay que descansar 45 horas es incorrecta, ya que no contempla la posibilidad de los descansos semanales reducidos.', 'Reglamento Comunitario (CE) 561/2006 Art. 8.6'),
('cap-564e176f155e', 'Para aprovechar la inercia y ahorrar carburante, lo mejor es dejar de acelerar con antelación, manteniendo una marcha engranada y sin pisar el embrague. De esta forma, el motor es arrastrado por las ruedas y el consumo de combustible es nulo. Si se reduce a una marcha más corta o se usan los frenos o ralentizadores, se disipa la energía de la inercia en forma de calor, lo que implica un mayor consumo.', NULL),
('cap-568bff0ba6d8', 'Un Estado miembro puede sancionar infracciones de tiempos de conducción y descanso que se hayan cometido en otro Estado, siempre que las descubra en su propio territorio y no hayan sido sancionadas ya. Esto evita la impunidad de las infracciones y asegura que se aplique la normativa. La idea de que solo el Estado donde se comete la infracción puede sancionar es incorrecta, ya que la normativa europea busca una aplicación más amplia para garantizar la seguridad. Tampoco es cierto que se pueda sancionar siempre, ya que debe haber un descubrimiento en el territorio del Estado que sanciona y la infracción no debe haber sido sancionada previamente.', NULL),
('cap-568c8625afec', 'El tacógrafo es obligatorio para el transporte de viajeros por carretera cuando no se trata de servicios regulares de línea de corto recorrido o transportes privados particulares. Un autocar que traslada trabajadores a un congreso realiza un transporte discrecional de viajeros, por lo que debe usar tacógrafo. Los autocares que hacen líneas regulares de menos de 50 km están exentos. Los vehículos de menos de 9 plazas no necesitan tacógrafo, y los transportes realizados por la policía están exentos.', NULL),
('cap-56a5c5d4a34c', 'La autorización OT es la que permite realizar actividades de operador de transporte, que engloba las actividades complementarias. Las otras opciones, como la de almacenista-distribuidor o la de transitario, son actividades complementarias específicas que se incluyen dentro de la autorización OT, no son la autorización general que permite el ejercicio de actividades complementarias. La autorización para estaciones de mercancías y centros logísticos es una infraestructura, no una actividad complementaria del transporte en sí misma.', NULL),
('cap-56c777cd853d', 'El balanceo es un movimiento de oscilación lateral. Cuanto más alto esté el centro de gravedad del camión respecto al eje de balanceo, mayor será el brazo de palanca que ejerce la fuerza centrífuga en las curvas, lo que amplifica el efecto de balanceo. Por eso, un centro de gravedad más elevado aumenta la inestabilidad y el riesgo de vuelco. La lluvia no influye directamente en el balanceo, sino en la adherencia.', NULL),
('cap-56d7c53453fe', 'Cuando pides ayuda especializada tras un accidente, es fundamental dar toda la información posible. Avisar por los postes SOS o el 112 es el primer paso para contactar. Luego, debes identificar claramente el lugar del accidente y describir lo que ha pasado para que los servicios de emergencia sepan a qué se enfrentan. También es crucial comunicar el número de heridos y su estado, ya que esto permite movilizar los recursos sanitarios adecuados. Por lo tanto, todas las acciones mencionadas son necesarias para una solicitud de ayuda eficaz.', NULL),
('cap-56dcb021f7f0', 'Una alimentación inadecuada, con comidas pesadas o irregulares, puede provocar digestiones lentas y pesadez, lo que directamente aumenta la sensación de fatiga. Además, la falta de nutrientes esenciales o un exceso de azúcares simples pueden afectar los niveles de energía y la capacidad del cerebro para mantener la atención, reduciendo así la concentración. Por lo tanto, una mala alimentación tiene un impacto negativo tanto en la fatiga como en la concentración. Pensar que solo afecta a la concentración o solo a la fatiga es un error, ya que ambos aspectos están interconectados con la nutrición.', NULL),
('cap-56ecdc1eb98c', 'Para que un transporte sea privado complementario, la actividad principal de la empresa NO puede ser el transporte. El transporte debe ser un complemento a su actividad principal, como indica la Ley 16/1987 Art. 102. Si la actividad principal fuera el transporte, estaríamos hablando de transporte público. Las mercancías deben tener relación con la empresa, el vehículo debe estar integrado en su organización y el conductor debe ser personal de la empresa, esos son requisitos correctos para el transporte privado complementario.', 'Ley 16/1987 Art. 102'),
('cap-56f1400c9cee', 'Parar el motor en detenciones cortas, como un semáforo, no compensa el consumo extra de combustible que se produce al volver a arrancar. Además, los arranques y paradas frecuentes aumentan el desgaste de componentes como el motor de arranque y la batería. Por eso, solo es eficiente apagar el motor cuando la detención va a ser lo suficientemente larga, como más de dos minutos, para que el ahorro de combustible compense el gasto del arranque y el desgaste. Decir que se debe parar en todas las detenciones es incorrecto por el mayor consumo y desgaste que implica.', NULL),
('cap-56f9f08971b5', 'El consumo específico mide la cantidad de combustible que necesita un motor para producir una unidad de potencia en un tiempo determinado. Si un motor tiene un menor consumo específico, significa que necesita menos combustible para generar la misma potencia, lo que indica que está aprovechando mejor la energía del combustible. Por lo tanto, un menor consumo específico se traduce directamente en un mayor rendimiento del motor. La cantidad de litros cada 100 kilómetros es el consumo de combustible, no el consumo específico, y no indica directamente el rendimiento.', NULL),
('cap-572493aa1b7a', 'La fuerza máxima de combustión no se produce al pisar el acelerador a fondo. Aunque se inyecte la máxima cantidad de carburante, el motor no tiene suficiente aire ni tiempo para quemarlo completamente. Esto significa que parte del combustible no se quema de forma eficiente, impidiendo alcanzar la fuerza máxima. La idea de que las resistencias de rozamiento son máximas al pisar a fondo no tiene relación directa con la fuerza de combustión.', NULL),
('cap-5754455c54d4', 'La actividad de transporte, por su propia naturaleza, implica la circulación de vehículos y, por tanto, el riesgo inherente de sufrir o provocar accidentes de tráfico. Este es uno de los principales riesgos asociados directamente a la conducción profesional. Las jornadas de trabajo de corta duración no son un riesgo, sino una medida preventiva o una condición laboral deseable. El trabajo relajado es lo contrario a un riesgo, y el transporte profesional conlleva un riesgo económico considerable, no poco.', NULL),
('cap-577ef4cc2f9b', 'La toma de decisiones es el proceso mental que nos permite elegir la mejor acción entre varias opciones disponibles al conducir. Implica evaluar la situación, considerar las posibles consecuencias de cada alternativa y seleccionar la que consideramos más segura o eficiente. La percepción del riesgo es solo una parte de este proceso, ya que primero hay que identificar el riesgo para luego poder decidir cómo actuar.', NULL),
('cap-57cc3d820157', 'Para solicitar ayuda eficazmente, lo primero es dar la información esencial: dónde ha ocurrido el accidente y qué ha pasado. Esto permite a los servicios de emergencia saber a dónde ir y qué recursos movilizar. Llamar a un número grabado en el teléfono del conductor accidentado o a los familiares de los heridos no es la forma correcta de pedir ayuda de emergencia, ya que no son los servicios de emergencia quienes deben acudir al lugar.', NULL),
('cap-57ce5f85806b', 'La tarjeta de tacógrafo que identifica al conductor y registra su actividad es la tarjeta de conductor. Esta tarjeta es personal e intransferible, y es obligatoria para registrar los tiempos de conducción y descanso. El Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado 1.t (3821/85) la define específicamente para este fin. La tarjeta de empresa, por ejemplo, es para que la empresa pueda descargar los datos de los vehículos, no para identificar al conductor.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado 1.t (3821/85)'),
('cap-57cf5a2ab7eb', 'La elaboración de nóminas es una tarea de gestión de personal y contabilidad, funciones que recaen en el departamento administrativo de la empresa. El conductor se encarga de la conducción y el transporte. El gerente se ocupa de la dirección general y la estrategia, mientras que el comercial se dedica a la venta y captación de clientes.', NULL),
('cap-580730be2874', 'Un vehículo muy cargado requiere más energía para moverse, lo que se traduce en un mayor consumo de carburante. El motor tiene que hacer un esfuerzo superior para desplazar esa masa adicional. Además, la aceleración será menor y la distancia de detención aumentará, no disminuirá, debido a la mayor inercia del conjunto.', NULL),
('cap-5807b84d2ec3', 'La necesidad de cumplir horarios preestablecidos es una fuente importante de estrés porque el conductor siente la presión de llegar a tiempo, lo que puede llevar a prisas y decisiones arriesgadas. Esta presión se agrava si surgen imprevistos en la ruta, como atascos o problemas con el vehículo. Cumplir los tiempos de conducción y descanso, por el contrario, es una obligación que, aunque requiere planificación, está diseñada para proteger al conductor y evitar la fatiga, no para estresarlo. El uso del limitador de velocidad es una herramienta de seguridad que ayuda a mantener una velocidad constante y legal, reduciendo la necesidad de estar pendiente del velocímetro y, por tanto, disminuyendo el estrés.', NULL),
('cap-5824b0ab2a67', 'Una dosis excesiva de café puede provocar ansiedad, ya que la cafeína es un estimulante del sistema nervioso central. Aunque el café puede ayudar a mantener la vigilia y aliviar la fatiga en dosis moderadas, un exceso puede llevar a efectos adversos. La mejora de los reflejos no es un efecto directo ni garantizado de una dosis excesiva, y el alivio de la fatiga y el mantenimiento de la vigilia son efectos positivos que se anulan con una dosis excesiva, que puede generar más problemas que soluciones.', NULL),
('cap-583c2667c462', 'El entorno de trabajo debe ser lo más silencioso posible para evitar distracciones y fatiga auditiva, lo que mejora la concentración y la seguridad. La iluminación y la temperatura deben ser adecuadas, no insuficientes o inadecuadas, para garantizar el confort y la visibilidad. Las vibraciones son perjudiciales y deben minimizarse, no estar presentes.', NULL),
('cap-584a5e9adb8e', 'El buen mantenimiento del vehículo, una conducción eficiente y seleccionar la marcha adecuada son factores clave que influyen directamente en el consumo de carburante. Un vehículo bien mantenido funciona de forma más eficiente, una conducción suave y anticipada reduce el gasto, y usar la marcha correcta evita forzar el motor. El tipo de bomba de alimentación, las bujías o el sistema de frenado no tienen un impacto directo y significativo en el consumo de combustible.', NULL),
('cap-588b0ffdfe74', 'Un sistema IVMS (In-Vehicle Monitoring System) se centra en la gestión y monitorización del vehículo y la carga. Su función principal es proporcionar datos para optimizar la operación, incluyendo la estimación de los tiempos de entrega de las mercancías, lo que es crucial para la planificación logística. Las alertas de salida de carril, los avisos de obstáculos y el análisis de la velocidad angular de las ruedas son funciones de sistemas de seguridad activa o de control del vehículo, no directamente de un IVMS.', NULL),
('cap-58b3008de21f', 'La normativa española para conductores autónomos distingue entre el tiempo que el conductor está activamente trabajando y el tiempo en el que, sin estar conduciendo o realizando otras tareas, debe estar disponible para reanudar el trabajo. El tiempo de descanso es un concepto diferente al de disponibilidad, ya que durante el descanso el conductor no está a disposición del trabajo. El tiempo de espera o efectivo son términos que no se utilizan en esta clasificación específica.', NULL),
('cap-58b73e0c9caa', 'El documento que autoriza el transporte internacional de mercancías por carretera en la Unión Europea se denomina "Licencia comunitaria". Así lo establece el Reglamento Comunitario (CE) 1072/2009 en su Artículo 4, que describe este documento y sus condiciones de expedición y uso. Las opciones como "Permiso comunitario" o "Autorización comunitaria" no son la denominación oficial de este documento. La "Tarjeta de transporte de la Unión" es una denominación incorrecta, ya que el documento oficial es la Licencia comunitaria.', 'Reglamento Comunitario (CE) 1072/2009 Art. 4'),
('cap-58c047bbc9a2', 'Para mantener la vigencia de la tarjeta CAP, es obligatorio realizar un curso de formación continua cada cinco años. Este curso actualiza los conocimientos del conductor sobre la normativa y las técnicas de conducción. No es necesario superar un examen después de este curso, solo la asistencia y aprovechamiento del mismo. La tarjeta CAP no tiene vigencia indefinida, sino que requiere esta formación periódica para su renovación.', NULL),
('cap-58c8be473f46', 'Cuando le pides más potencia al motor, este necesita quemar más combustible para generarla, lo que directamente aumenta el consumo. Es una relación directa: para conseguir más fuerza o velocidad, el motor tiene que trabajar más y, por tanto, "beber" más. Pensar que a menor potencia hay mayor consumo es incorrecto, ya que un motor que trabaja menos consume menos combustible.', NULL),
('cap-58d1b97f9307', 'El conductor profesional debe evaluar constantemente el riesgo en la carretera y ajustar su comportamiento a lo que está dispuesto a asumir. Esto implica tomar decisiones activas sobre la velocidad, la distancia de seguridad y las maniobras. No se trata de maximizar o minimizar las consecuencias de un accidente, sino de gestionar la probabilidad de que ocurra. Aunque incrementar la atención es importante, la acción final se basa en la asunción de riesgo.', NULL),
('cap-590896758a27', 'Una garantía global significa que no se limita a una única operación de transporte, sino que puede cubrir varias. Esto facilita los trámites para los transportistas que realizan múltiples envíos en régimen de tránsito. El Reglamento Comunitario (UE) 952/2013 Art. 89, apartado 5, lo confirma al permitir una garantía global para cubrir dos o más operaciones, declaraciones o regímenes aduaneros. Que cubra a varios operadores o a todos los de un país o asociación no es lo que define el carácter global de la garantía en este contexto.', 'Reglamento Comunitario (UE) 952/2013 Art. 89'),
('cap-596653a661a7', 'Después de poner las cadenas, es fundamental circular unos 500 metros para que se asienten bien en el neumático. Al circular, las cadenas se ajustan y se colocan correctamente, lo que evita que se suelten o se dañen. Tras ese recorrido, hay que parar y verificar que siguen bien puestas y tensas. La opción de detenerse a los 100 metros para tensarlas y a los 50 metros para comprobar la holgura es incorrecta porque el recorrido es demasiado corto para que las cadenas se asienten de forma efectiva.', NULL),
('cap-598578d0d575', 'La declaración amistosa de accidente es un documento fundamental para agilizar los trámites con las aseguradoras. Para que sea útil, debe contener toda la información relevante del siniestro. Es imprescindible anotar el lugar exacto del accidente, los datos completos de las compañías de seguros de los vehículos implicados y una descripción de los daños visibles en cada vehículo. Sin estos datos, la declaración no cumpliría su función de facilitar la gestión del siniestro.', NULL),
('cap-598bb012842f', 'Nunca debemos dar medicamentos a los heridos en un accidente. No somos personal sanitario y podríamos empeorar su estado o provocarles una reacción adversa. Aunque el objetivo sea aliviar el dolor, solo el personal médico cualificado puede administrar fármacos. La idea de dar medicamentos si están conscientes y lo piden es un error, ya que no tenemos la formación para saber qué es seguro para ellos.', NULL),
('cap-598f2ddafbc1', 'La Ley Orgánica 4/2000 Art. 66.1 establece que las obligaciones en materia de extranjería se aplican a cualquier compañía, empresa de transporte o transportista, sin importar el medio. Esto incluye el transporte aéreo, marítimo y terrestre. La normativa busca combatir la inmigración ilegal y garantizar la seguridad pública en todos los ámbitos del transporte. Las opciones que limitan la responsabilidad a un solo tipo de transporte o excluyen el terrestre son incorrectas porque la ley es clara al incluir los tres medios.', 'Ley Orgánica 4/2000 Art. 66.1'),
('cap-5991c047e07c', 'La Ley 16/1987 Art. 143.4 establece los supuestos en los que se debe inmovilizar un vehículo. La falta de uniformidad del conductor no está contemplada como motivo de inmovilización en esta normativa. Sin embargo, el exceso de peso, los excesos en los tiempos de conducción o la minoración de los tiempos de descanso, si son infracciones graves o muy graves, sí son causas de inmovilización del vehículo.', 'Ley 16/1987 Art. 143.4'),
('cap-59a06a269320', 'Los amortiguadores en mal estado no pueden controlar adecuadamente el balanceo de la carrocería, lo que provoca una inclinación excesiva del vehículo al tomar una curva. Esto reduce la estabilidad y el agarre de los neumáticos. El desgaste de los bordes de la banda de rodadura suele indicar una presión incorrecta de los neumáticos o problemas de alineación, no directamente de amortiguadores.', NULL),
('cap-59aa35833c79', 'La aduana de destino es aquella donde se finaliza el régimen de tránsito, presentando las mercancías y la declaración de tránsito. Es el punto donde se cumplen las formalidades para dar por concluido el movimiento bajo ese régimen. La aduana más próxima al lugar de llegada no es necesariamente la de destino, ya que el tránsito debe finalizarse en una aduana específica, no solo en la más cercana geográficamente. La aduana de salida del territorio aduanero comunitario es la aduana de salida, no la de destino.', 'Reglamento Comunitario (UE) 2015/2446 Art. 1'),
('cap-59d0f965ba1b', 'La carencia de autorización de transporte es una infracción muy grave. La Ley 16/1987 Art. 143.4 establece que se debe inmovilizar el vehículo cuando se detectan en carretera infracciones muy graves. Por tanto, un autobús sin autorización de transporte será inmovilizado. La inmovilización no depende de la reiteración ni del tipo de servicio, sino de la gravedad de la infracción.', 'Ley 16/1987 Art. 143.4'),
('cap-59dcb9e0eae6', 'El balanceo es el movimiento de la carrocería que gira sobre el eje longitudinal del camión, es decir, el que va de delante hacia atrás. Es como si el camión se inclinara de lado a lado, algo que ocurre al tomar curvas o con viento lateral. El movimiento de giro sobre el eje vertical se conoce como guiñada, y el movimiento giratorio sobre un eje transversal a la marcha es el cabeceo.', NULL),
('cap-59f4bacad643', 'Cuando el carburante no se quema por completo en los cilindros, significa que hay un exceso de combustible o una falta de aire en la combustión. Este combustible sin quemar se expulsa por el escape en forma de partículas de hollín, lo que provoca que el humo sea de color negro. El motor no se cala ni da tirones directamente por esto, y el ruido no es un indicador fiable de este problema.', NULL),
('cap-5a16f06dbc15', 'La prioridad es no agravar las posibles lesiones de la víctima, especialmente si hay daños internos o en la columna vertebral. Mover a un herido sin conocimiento médico puede causar lesiones permanentes o incluso la muerte. Solo se debe mover a la víctima si existe un peligro inminente, como un vehículo en llamas o riesgo de atropello. Dar líquidos o alimentos a un herido puede ser peligroso, especialmente si necesita cirugía o está inconsciente, ya que podría provocar atragantamiento o complicaciones.', NULL),
('cap-5a1bb49e823b', 'El transporte internacional de mercancías requiere una gran inversión en vehículos, tecnología y personal especializado, algo que solo las empresas grandes pueden afrontar. Además, estas empresas tienen la capacidad de establecer redes logísticas complejas y acuerdos con operadores en otros países. Las empresas pequeñas y medianas suelen tener recursos más limitados, lo que les dificulta competir en este ámbito.', NULL),
('cap-5a504015602e', 'Un camión alto tiene el centro de gravedad más elevado. Esto significa que el centro de gravedad está más lejos del eje de balanceo, lo que aumenta el brazo de palanca y, por tanto, la inclinación del vehículo ante la misma fuerza lateral. La opción que dice que se inclina menos porque el centro de gravedad está más cerca del eje de balanceo es incorrecta, ya que un centro de gravedad más alto siempre implica mayor distancia al eje de balanceo y mayor inclinación.', NULL),
('cap-5a72f7a7412a', 'El Convenio CMR Art. 6.1 establece que la carta de porte debe contener el lugar y la fecha de emisión, el lugar y la fecha de la carga de la mercancía, el lugar previsto para su entrega, y el nombre y domicilio del transportista, del remitente y del destinatario. Por lo tanto, todas las indicaciones mencionadas son obligatorias. No se puede omitir ninguna de estas informaciones, ya que son esenciales para la validez y el seguimiento del transporte internacional por carretera.', 'Convenio CMR Art. 6.1'),
('cap-5a92d3fc0e93', 'Para aprovechar la inercia, es fundamental conducir con anticipación y previsión, lo que permite anticipar frenadas y aceleraciones innecesarias. Mantener una distancia de seguridad superior a la habitual te da más espacio para reaccionar y gestionar la inercia sin brusquedades. Además, mantener la velocidad media constante, evitando acelerones y frenazos, contribuye a un uso eficiente de la inercia del vehículo.', NULL),
('cap-5a9cf17c4faa', 'La junta general ordinaria de una sociedad anónima tiene que reunirse obligatoriamente dentro de los seis primeros meses de cada ejercicio. Así lo establece el RD Legislativo 1/2010 Art. 164.1, que es la normativa que regula estas sociedades. El objetivo es aprobar la gestión y las cuentas del ejercicio anterior. Reunirse dentro de los tres primeros meses es un error común, pero el plazo legal es más amplio.', 'RD Legislativo 1/2010 Art. 164.1'),
('cap-5ab364448453', 'El índice de mortalidad mide la relación entre el número de fallecidos y los kilómetros recorridos, lo que nos da una idea de la letalidad de los accidentes en función de la distancia. El índice de peligrosidad se refiere a la probabilidad de sufrir un accidente, no a los fallecidos. El índice de gravedad se centra en la severidad de las lesiones, no exclusivamente en los fallecidos.', NULL),
('cap-5ade0a82199b', 'La aerodinámica del vehículo es crucial porque una mayor resistencia al aire obliga al motor a trabajar más para mantener la velocidad, aumentando directamente el consumo de carburante. Un diseño aerodinámico reduce esta resistencia, mejorando la eficiencia. El tipo de ralentizador no influye en el consumo, ya que su función es frenar el vehículo, no propulsarlo.', NULL),
('cap-5aff96ee76ac', 'No se puede extraer la tarjeta del tacógrafo digital con el vehículo en movimiento. El tacógrafo está diseñado para registrar la actividad del conductor de forma continua mientras el vehículo está en marcha, y la extracción de la tarjeta interrumpiría este registro. Esto es una medida de seguridad y control para asegurar la fiabilidad de los datos. La idea de que se puede extraer la tarjeta por debajo de cierta velocidad es incorrecta, ya que la normativa no contempla excepciones por velocidad para la extracción de la tarjeta con el vehículo en movimiento.', 'Reglamento Comunitario (UE) 165/2014 Anexo IB, apartado III, 1 (3821/85)'),
('cap-5b2dd56792c7', 'El nivel negro en una carretera por nevada significa que la vía está intransitable y, por tanto, cortada al tráfico. Esto implica la prohibición total de circular para cualquier vehículo. La restricción no se limita a vehículos pesados o camiones, ni a un horario específico, sino que afecta a todos los usuarios por igual.', 'Resolución D.G. Tráfico 01/06/2009 Anexo I'),
('cap-5b5c90f5ee7c', 'El transporte de mercancías que realiza una empresa para apoyar su actividad principal, sin que el transporte sea su negocio, se denomina transporte privado complementario. La Ley 16/1987 Art. 102 lo define así, estableciendo que es un complemento necesario para el desarrollo de su actividad. La opción de transporte privado productivo no es la terminología correcta para este tipo de actividad.', 'Ley 16/1987 Art. 102'),
('cap-5b84645f7f68', 'Para realizar cabotaje, no es obligatorio entrar en el país de acogida con un transporte internacional previo. El Reglamento Comunitario (CE) 1072/2009 Art. 8 permite entrar en vacío en un Estado miembro y realizar un transporte de cabotaje en los tres días siguientes a esa entrada. La opción que indica que siempre se requiere entrar con un transporte internacional es incorrecta, ya que la normativa contempla la entrada en vacío bajo ciertas condiciones.', 'Reglamento Comunitario (CE) 1072/2009 Art. 8'),
('cap-5b960e9353d2', 'La técnica de transportar camiones completos en tren se denomina "carretera rodante" o "autopista rodante". El término "carretera rodante" es el más preciso y comúnmente aceptado para describir este sistema de transporte intermodal. La opción "carretera rodada" no es un término técnico reconocido en el transporte. "Tren rodante" no es correcto porque el tren es el medio de transporte, no la técnica en sí.', NULL),
('cap-5bdb3c0a348a', 'La clave MDPE identifica una autorización de transporte público de mercancías de ámbito nacional. Esto significa que permite realizar tanto transporte urbano como interurbano por todo el territorio español. La OM FOM/734/2007 Art. 6 confirma que estas autorizaciones habilitan para el transporte en todo el Estado sin limitaciones de radio de acción. Por lo tanto, las opciones que limitan el transporte a un radio de kilómetros o a una Comunidad Autónoma son incorrectas.', 'OM FOM/734/2007 Art. 6'),
('cap-5be6f1cca4c5', 'La declaración amistosa de accidente es una herramienta que simplifica el proceso de reclamación. Al rellenarla correctamente en el lugar del siniestro, se proporciona a las aseguradoras toda la información necesaria de forma clara y concisa. Esto evita demoras y agiliza tanto la tramitación como el pago de las indemnizaciones. Pensar que consigue mayores indemnizaciones es un error, su función es la eficiencia, no el aumento de la cuantía.', 'Convenio CIDE Art. Preliminar'),
('cap-5be8f65677b4', 'Los vehículos pesados y autobuses tienen una masa y un tamaño considerablemente mayores que un turismo. Esta diferencia de masa implica que, en caso de colisión, la energía cinética involucrada es mucho mayor, lo que se traduce en daños más severos y un mayor riesgo de lesiones graves o mortales. Por lo tanto, las consecuencias de un accidente con estos vehículos son generalmente más graves. Pensar que no habrá consecuencias negativas por las medidas de seguridad es un error, ya que estas medidas mitigan, pero no eliminan el riesgo inherente a la masa y tamaño del vehículo.', NULL),
('cap-5be93eea33ec', 'La inercia es la resistencia de un cuerpo a cambiar su estado de movimiento. Cuanta más masa tiene un vehículo, más inercia posee. Del mismo modo, a mayor velocidad, mayor será la inercia que deberá vencerse para detenerlo o cambiar su trayectoria. El volumen del vehículo no influye directamente en la inercia, ya que un vehículo puede ser voluminoso pero ligero, o compacto y muy pesado.', NULL),
('cap-5c02db2096a3', 'La energía acumulada, o energía cinética, es la que tiene un vehículo en movimiento. Esta energía depende directamente de dos factores: la masa del vehículo y su velocidad. Cuanta más masa o más velocidad tenga el vehículo, mayor será su energía acumulada. Decir que depende solamente de la masa o solamente de la velocidad es un error, ya que ambos factores son cruciales para determinarla.', NULL),
('cap-5c09043bf383', 'La modificación de la Directiva CAP en 2018 buscó mejorar la claridad en la aplicación de la normativa, armonizar las edades mínimas para obtener los permisos de conducción profesionales y permitir el uso del aprendizaje electrónico en la formación. Por lo tanto, todas las opciones mencionadas son objetivos de esa modificación. No se trata de un único objetivo, sino de una serie de mejoras integrales.', NULL),
('cap-5c0af91e0800', 'Los almacenistas-distribuidores se consideran operadores de transporte de mercancías porque su actividad incluye la organización y gestión del movimiento de las mercancías, ya sea con medios propios o ajenos. La OM 21/07/2000 Arts. 1 y 2 así lo establece al definir el ámbito de los operadores. No importa si usan vehículos propios o contratan a otros transportistas; la clave es que gestionan la distribución. La idea de que solo se incluyen si contratan a empresas transportistas es incorrecta, ya que la definición abarca ambas modalidades.', 'OM 21/07/2000 Arts. 1 y 2'),
('cap-5c296d3da3e5', 'Las paradas frecuentes, como máximo cada dos horas, son esenciales para prevenir el sueño. Permiten descansar la vista, estirar las piernas y despejarse, lo que ayuda a mantener la concentración al volante. Realizar comidas copiosas o mantener una temperatura muy alta en el habitáculo favorecen la somnolencia, y aunque el café puede parecer una solución, su efecto es temporal y puede generar un "efecto rebote" de cansancio.', NULL),
('cap-5c9769816030', 'Para la distribución de mercancías peligrosas, se busca minimizar el riesgo. Las carreteras convencionales suelen tener menos tráfico y velocidades más bajas que las autovías, lo que reduce la probabilidad de accidentes graves. Además, al recorrer la mínima distancia posible, se acorta el tiempo de exposición al riesgo. La idea de que el transportista puede elegir libremente el itinerario es incorrecta, ya que existen normativas específicas para el transporte de mercancías peligrosas que restringen la libre elección.', NULL),
('cap-5cb901697e0f', 'La deriva es el ángulo que se forma entre la dirección a la que apunta el neumático y la dirección real en la que se mueve el vehículo. La pérdida de adherencia, en cambio, es cuando el neumático ya no tiene agarre con la superficie de la carretera. No son lo mismo, aunque una deriva excesiva puede llevar a una pérdida de adherencia. La afirmación de que la falta de adherencia puede provocar un derrape es cierta, pero eso no significa que deriva y pérdida de adherencia sean lo mismo.', NULL),
('cap-5cbc4109f920', 'El acto de comprobar periódicamente que se mantienen los requisitos de las autorizaciones de transporte se denomina visado periódico. La Ley 16/1987, en su Artículo 51, establece que la validez de las autorizaciones puede estar condicionada a este visado. Mediante el visado, la Administración comprueba que se siguen cumpliendo las condiciones exigidas. Las autorizaciones que no se visen en plazo pierden su validez automáticamente. La opción de "revisión periódica" no es la terminología legal correcta para este procedimiento administrativo.', 'Ley 16/1987 Art. 51'),
('cap-5cc5e7d4d52c', 'La declaración amistosa de accidente es un documento para agilizar la gestión de siniestros entre aseguradoras. Para que sea válida y cumpla su función, es imprescindible que todos los vehículos implicados tengan el seguro de responsabilidad civil obligatorio en vigor. Sin seguro, la declaración no tiene validez para las compañías. La afirmación de que es válida sin seguro es incorrecta porque el seguro es la base de este sistema de declaración.', 'Convenio CIDE Art. 2'),
('cap-5cc737c3e453', 'Para que un conductor se considere dedicado al transporte internacional, debe iniciar dos descansos semanales reducidos consecutivos fuera del país donde está establecida la empresa y fuera de su lugar de residencia. Esta es la condición específica que establece la normativa para diferenciar el transporte internacional a efectos de los descansos semanales. Las opciones que hablan de porcentajes de jornadas en otros países no son correctas para definir el transporte internacional en este contexto.', NULL),
('cap-5ce2fb021a9c', 'La tarjeta de empresa es la que identifica a la compañía y le permite gestionar los datos de los tacógrafos de sus vehículos, como ver, descargar o imprimir la información. La tarjeta de conductor, en cambio, es personal e intransferible y registra la actividad de un conductor específico. La tarjeta de centro de ensayo es para los talleres autorizados que calibran y revisan los tacógrafos.', NULL),
('cap-5d3863a2d7ca', 'Los incendios en vehículos suelen originarse por problemas eléctricos, como cortocircuitos o cables en mal estado, que generan chispas o sobrecalentamiento. Las fugas de combustible son muy peligrosas, ya que el combustible es inflamable y puede prenderse fácilmente al entrar en contacto con una fuente de calor. El sobrecalentamiento del motor también puede provocar un incendio, especialmente si hay líquidos inflamables cerca o si el calor es excesivo. Por lo tanto, todas las causas mencionadas son factores comunes en los incendios de vehículos.', NULL),
('cap-5d425105f4ad', 'El Convenio CMR, en su Artículo 27, establece claramente que se pueden exigir intereses sobre las indemnizaciones por pérdida o deterioro de la mercancía. Estos intereses empiezan a contar desde el día en que se presenta una reclamación escrita al transportista. La reclamación debe ser por escrito para que tenga validez a efectos de iniciar el cómputo de los intereses. La limitación de responsabilidad a 8,33 unidades de cuenta por kilogramo se refiere al principal de la indemnización, no a los intereses que se puedan generar.', 'Convenio CMR Art. 27'),
('cap-5d575561d828', 'En una frenada de emergencia sin ABS, hay que pisar el freno con decisión para detener el vehículo lo antes posible. Sin embargo, es crucial evitar que las ruedas se bloqueen, ya que esto provocaría la pérdida de control y un aumento de la distancia de frenado. Frenar de forma brusca o suavemente no es lo adecuado; la primera opción puede bloquear las ruedas y la segunda no detendrá el vehículo a tiempo. Accionar el freno de mano en una emergencia es muy peligroso, ya que puede desestabilizar el vehículo.', NULL),
('cap-5d64d0507441', 'La resistencia de la pendiente es una fuerza que se opone al movimiento del vehículo cuando este circula cuesta arriba, ya que la gravedad tira del vehículo hacia abajo. Esta resistencia es una de las principales que el motor debe vencer para mantener la velocidad o acelerar. El uso del aire acondicionado o del ralentizador son consumos energéticos o sistemas de frenado, no resistencias al movimiento del vehículo. La resistencia al movimiento de la caja de velocidades es una pérdida interna del sistema de transmisión, no una resistencia externa que el vehículo deba superar para moverse.', NULL),
('cap-5da0cf149bc9', 'El cuaderno TIR es el documento aduanero que ampara las mercancías transportadas bajo el régimen TIR, facilitando su tránsito por diferentes países sin necesidad de despachos aduaneros en cada frontera. Su función principal es acompañar a la mercancía durante todo el trayecto. No es un conjunto de normas, ni autoriza vehículos, ni acredita al conductor.', 'Convenio TIR Art. 17'),
('cap-5ddd7d1d0ed9', 'El Reglamento Comunitario (CE) 561/2006 Art. 8.6 establece claramente que en dos semanas consecutivas el conductor debe tomar dos períodos de descanso semanal normal, o bien un período de descanso semanal normal y uno reducido de al menos 24 horas. Ambas combinaciones son válidas y cumplen con la normativa. La opción de tomar dos períodos de descanso semanal reducidos de al menos 24 horas no es correcta porque la normativa exige al menos un descanso semanal normal en ese periodo de dos semanas.', 'Reglamento Comunitario (CE) 561/2006 Art. 8.6'),
('cap-5de43c395a88', 'Para ahorrar carburante, debes mantener una marcha larga el mayor tiempo posible. Reducir de marcha implica que el motor aumente sus revoluciones, lo que incrementa el consumo de combustible. Por lo tanto, es más eficiente apurar la marcha larga antes de reducir. La reducción de marchas sí influye directamente en el consumo.', NULL),
('cap-5df7e8b2b7ce', 'Los líquidos envasados en botellas o bidones deben transportarse siempre de pie, asentados sobre sus bases. Esto minimiza el riesgo de derrames y fugas, ya que la mayoría de los envases están diseñados para ser más estancos en esa posición. Además, al ir de pie, se reduce el movimiento del líquido dentro del envase, lo que contribuye a la estabilidad de la carga. Transportarlos tumbados, ya sea transversal o longitudinalmente, aumenta la superficie de contacto del líquido con el cierre y la presión sobre este, facilitando las fugas.', NULL),
('cap-5e0f65ae80c0', 'La capacidad de reaccionar rápidamente ante imprevistos es una de las grandes ventajas del transporte por carretera. Permite ajustar rutas, horarios o incluso el tipo de vehículo con agilidad para minimizar el impacto de cualquier problema. Afirmar que el transporte por carretera no tiene reacciones ágiles es incorrecto, ya que su flexibilidad es superior a la de otros modos.', NULL),
('cap-5e4d7b2de5b6', 'La Ley 31/1995, en sus artículos 14 y 29, establece claramente que la prevención de riesgos laborales es una responsabilidad compartida. El empresario tiene el deber de garantizar la seguridad y salud de los trabajadores, mientras que el trabajador debe velar por su propia seguridad y la de terceros, cumpliendo las medidas de prevención. La idea de que es una obligación exclusivamente del trabajador es incorrecta, ya que el empresario es el principal responsable de establecer las condiciones seguras.', 'Ley 31/1995 Arts. 14 y 29'),
('cap-5e8beebf1491', 'La potencia de un motor es el resultado de multiplicar el par motor por el número de revoluciones. Por lo tanto, a mayor número de revoluciones, mayor potencia. Aunque la cilindrada influye en el par motor, no es el factor que más directamente determina la potencia final. El grado de llenado de los cilindros y la relación de compresión afectan al rendimiento y al par, pero la potencia es directamente proporcional a las revoluciones.', NULL),
('cap-5ec479cbb861', 'Los medicamentos de categoría 0 son aquellos que no afectan en absoluto la capacidad para conducir. Por lo tanto, no hay necesidad de dar ninguna advertencia específica al conductor. Las otras opciones son incorrectas porque implican una precaución que no es necesaria para esta categoría de medicamentos.', NULL),
('cap-5eea2287c2ad', 'La limpieza del vehículo la puede hacer la propia empresa transportista. Lo fundamental es que los productos de limpieza y desinfección sean aptos para el contacto con alimentos y que se tenga la documentación que lo demuestre. No es necesario que el personal tenga una formación oficial específica para esta tarea, sino que se sigan los procedimientos correctos con los productos adecuados. Tampoco es obligatorio que la limpieza la haga un centro externo especializado.', NULL),
('cap-5ef2b3ebe932', 'Las sociedades de capital, como la sociedad anónima, siempre tienen carácter mercantil, independientemente de la actividad a la que se dediquen. Así lo establece el RD Legislativo 1/2010 Art. 2. Por tanto, no es correcto pensar que su carácter dependa de si su objeto social es mercantil o civil.', 'RD Legislativo 1/2010 Art. 2'),
('cap-5ef340787a05', 'El transporte de mercancías está directamente ligado a la actividad económica general. Cuando hay una crisis, disminuye la producción y el consumo, lo que reduce la necesidad de mover mercancías. Por eso, el sector del transporte se resiente y experimenta una caída en su actividad. Pensar que aumenta en crisis es un error, ya que la demanda de transporte está ligada a la salud económica.', NULL),
('cap-5f10ea838238', 'Aunque no pises el acelerador y el motor esté desembragado, el motor sigue girando y necesita combustible para mantener su ralentí. El motor no se detiene, por lo que siempre habrá un mínimo consumo para que siga funcionando. La creencia de que el consumo es nulo en estas condiciones es un error común, ya que el motor no se apaga.', NULL),
('cap-5f2100a33707', 'Si un herido no tiene pulso, significa que su corazón no bombea sangre y, por tanto, no llega oxígeno a sus órganos vitales. El masaje cardiaco ayuda a que la sangre circule, pero es fundamental combinarlo con la respiración boca a boca para introducir oxígeno en los pulmones y que este pueda ser transportado por la sangre. Ambas acciones son cruciales para intentar reanimar a la persona. La ingesta de líquidos calientes o el vertido de agua fría no tienen ninguna utilidad en una parada cardiorrespiratoria.', NULL),
('cap-5f35a6eff14e', 'La suspensión está diseñada para absorber las irregularidades del terreno, lo que se traduce directamente en una mejora del confort para el conductor y los ocupantes. Aunque la suspensión ayuda a controlar el balanceo y el cabeceo, su función principal es aislar el habitáculo de las vibraciones. Que las imperfecciones del terreno se transmitan al habitáculo es justo lo contrario de lo que busca la suspensión.', NULL),
('cap-5f41957d1b14', 'Los transportes postales efectuados en régimen de servicio universal están liberalizados en la Unión Europea, lo que significa que no necesitan licencia comunitaria ni autorización de transporte. Esto se establece claramente en el Reglamento Comunitario (CE) 1072/2009 Art. 1.5. Los transportes de productos hortofrutícolas no están incluidos en esta exención, independientemente de su origen.', 'Reglamento Comunitario (CE) 1072/2009 Art. 1.5'),
('cap-5f4284e45856', 'Los transportes de mercancías se clasifican en ordinarios y especiales por la especificidad de su objeto y su régimen jurídico, tal como establece la Ley 16/1987 Art. 66. Los transportes especiales son aquellos que, por su peligrosidad, urgencia o incompatibilidad, están sujetos a normas administrativas específicas. La clasificación de "discrecionales, nacionales e internacionales" se refiere a otras características del transporte, no a la especificidad de su objeto o régimen jurídico.', 'Ley 16/1987 Art. 66'),
('cap-5f4a59956d70', 'La junta general de socios que se convoca en los primeros seis meses del ejercicio para aprobar las cuentas anuales se denomina junta ordinaria. Su carácter es periódico y obligatorio para todas las sociedades anónimas. Las juntas extraordinarias se convocan para tratar asuntos urgentes o imprevistos que no pueden esperar a la junta ordinaria. La junta universal no requiere convocatoria previa, pero sí la presencia de todos los socios y que todos estén de acuerdo en celebrar la junta y en los puntos a tratar.', NULL),
('cap-5f4c5eeb980e', 'Marruecos no forma parte del Espacio Schengen. Este espacio se creó para eliminar los controles fronterizos internos entre los países participantes, facilitando la libre circulación de personas. España, Suiza e Islandia sí pertenecen al Espacio Schengen, ya sea como miembros de la Unión Europea o a través de acuerdos específicos, como se establece en el Acuerdo Adhesión del Reino de España al Convenio de aplicación del Acuerdo de Schengen;Acuerdos de la Unión Europea con la República de Islandia y el Reino de Noruega;y con la Confederación Suiza Art. 1.', 'Acuerdo Adhesión del Reino de España al Convenio de aplicación del Acuerdo de Schengen;Acuerdos de la Unión Europea con la República de Islandia y el Reino de Noruega;y con la Confederación Suiza Art. 1'),
('cap-5f5bb22b261d', 'El grado de concentración de anticongelante en el líquido refrigerante no influye directamente en el consumo de carburante. Su función principal es mantener la temperatura del motor dentro de un rango óptimo, evitando la congelación o el sobrecalentamiento, pero no afecta la eficiencia de la combustión. El perfil de la carretera, el número de revoluciones del motor y la presión de los neumáticos sí son factores que modifican el consumo de combustible.', NULL),
('cap-5f655b65cf6b', 'Un motor de mayor cilindrada tiene más volumen para la combustión, lo que permite quemar más mezcla de aire y combustible en cada ciclo. Esto genera una mayor fuerza y, por tanto, una mayor potencia. La idea de que a mayor cilindrada, menor potencia es incorrecta, ya que más volumen de combustión se traduce directamente en más energía liberada.', NULL),
('cap-5f6e424d0e71', 'Los fuegos de clase B son aquellos que involucran líquidos inflamables, como la gasolina, el gasóleo o los aceites, que son comunes en un autobús. Es crucial conocer esta clasificación para seleccionar el extintor adecuado. Un fuego de sólidos inflamables sería de clase A, y los términos ''fuego primario'' o ''secundario'' no son clasificaciones estándar de tipos de fuego.', NULL),
('cap-5f6fc9fe5e86', 'El Reglamento Comunitario (CE) 561/2006 Art. 8 establece que un período de descanso semanal reducido debe ser de al menos 24 horas. Esta es la duración mínima permitida para un descanso semanal cuando se aplica una reducción. Las opciones de 20, 28 o 30 horas no se corresponden con la normativa para el descanso semanal reducido.', 'Reglamento Comunitario (CE) 561/2006 Art. 8'),
('cap-5f8d463f12be', 'Para incluir mercancías en un régimen aduanero, se utilizan dos tipos de declaración: la normal y la simplificada. La declaración normal exige todos los datos necesarios para el régimen aduanero, mientras que la simplificada permite omitir algunos datos o documentos justificativos, previa autorización. Las opciones como "ordinaria y extraordinaria" o "común y específica" no corresponden a la terminología aduanera para este fin.', 'Reglamento Comunitario (UE) 952/2013 Art. 158;Art. 162;Art. 166'),
('cap-5f9ef3267f8b', 'La Ley 27/1999 Art. 19 establece claramente que la Asamblea General es uno de los órganos de la sociedad cooperativa. Este artículo también menciona el Consejo Rector y la Intervención como órganos. La junta general de accionistas es un órgano de las sociedades anónimas, no de las cooperativas. El consejo de administración es un órgano de las sociedades mercantiles, no de las cooperativas, que tienen un Consejo Rector. El comité de garantías de la cooperativa no es un órgano social, sino una instancia de carácter consultivo o asesor.', 'Ley 27/1999 Art. 19'),
('cap-5fb95381ffb0', 'La falta de sueño afecta negativamente al cerebro, disminuyendo la capacidad de concentración y el tiempo de reacción. Esto puede llevar a que el conductor se sienta más irritable y reaccione de forma más impulsiva, manifestándose como nerviosismo y agresividad al volante. Pensar que la falta de sueño aumenta la atención es un error grave, ya que ocurre justo lo contrario.', NULL),
('cap-5fc01f79ff1f', 'La imagen de marca se construye a partir de múltiples fuentes. La experiencia personal previa con la marca es fundamental, ya que es lo que el individuo ha vivido directamente. Las relaciones interpersonales, como las opiniones de amigos o familiares, también influyen mucho. Además, los medios de comunicación, a través de la publicidad o las noticias, juegan un papel importante en la percepción de una marca.', NULL),
('cap-5fcc6608c71a', 'Los extintores tienen diferentes tipos de revisiones con distintas periodicidades. La revisión trimestral es una comprobación básica, la anual es una revisión más exhaustiva por personal cualificado, y la quinquenal implica el retimbrado o prueba hidráulica. Por lo tanto, todas las periodicidades mencionadas son correctas para diferentes tipos de revisiones de extintores.', NULL),
('cap-5fdadbf805c1', 'Circular con marchas cortas obliga al motor a trabajar a un régimen de revoluciones más alto para mantener una velocidad determinada, lo que incrementa el consumo de combustible. Las marchas largas permiten que el motor trabaje a menos revoluciones, siendo más eficiente. Aprovechar la inercia del vehículo o circular a velocidad moderada son prácticas que, por el contrario, ayudan a reducir el consumo.', NULL),
('cap-603584180aac', 'La Administración debe asegurarse de que todas las instalaciones autorizadas, incluidas las sucursales, mantienen los requisitos que se les exigieron para su aprobación. Esto garantiza la calidad de la formación en todos los puntos de la empresa. No se trata de un control reactivo, sino de una supervisión continua para asegurar el cumplimiento. La idea de que el control solo se aplica a la empresa principal es incorrecta, ya que las sucursales también imparten formación CAP.', NULL),
('cap-605cae87099b', 'Las actuaciones de los agentes de seguridad en un accidente se documentan en el atestado, que es el informe oficial y detallado de lo ocurrido. Este documento es fundamental para determinar responsabilidades y para cualquier proceso legal posterior. Las actuaciones no se recogen en el parte de la grúa, ya que ese documento solo registra la retirada del vehículo.', NULL),
('cap-6097454faa96', 'Una caja de cambios con más marchas permite al conductor seleccionar la relación de transmisión más adecuada para cada situación, manteniendo el motor en su rango óptimo de revoluciones. Esto se traduce en una mayor eficiencia y, por tanto, en un menor consumo de combustible. Las cajas con menos marchas limitan esta capacidad de ajuste, lo que puede obligar al motor a trabajar fuera de su punto más eficiente. El tipo de caja de velocidades sí influye significativamente en el consumo.', NULL),
('cap-609acb1aac78', 'Un vehículo que opera exclusivamente dentro de un recinto portuario está exento del uso de tacógrafo. El RD 640/2007 Art. 2.o, apartado n), establece esta excepción para vehículos dedicados a servicios que se desarrollen íntegramente en recintos cerrados como puertos. No importa la Masa Máxima Autorizada del vehículo, la exención se aplica por el tipo de servicio y el lugar donde se realiza. Las opciones que mencionan la obligación de usar tacógrafo, ya sea digital o analógico, son incorrectas porque el vehículo está exento.', 'RD 640/2007 Art. 2.o'),
('cap-60a6667c51ff', 'El tipo de batería, sea con o sin mantenimiento, no tiene ninguna influencia en el consumo de carburante del vehículo. La batería solo se encarga de arrancar el motor y alimentar los sistemas eléctricos cuando el motor está parado. La relación de marchas, la presión de los neumáticos y la posición del pedal del acelerador sí afectan directamente al esfuerzo que hace el motor y, por tanto, al consumo de combustible. Pensar que la batería influye en el consumo es un error común, pero su función es independiente del rendimiento del motor una vez en marcha.', NULL),
('cap-60c964de6779', 'Un asiento debe permitir que el trabajador apoye los pies completamente en el suelo para mantener una postura correcta y evitar problemas de circulación o fatiga. Si los pies quedan colgando o no tocan el suelo, se fuerza una mala postura que puede generar molestias y lesiones a largo plazo. La altura adecuada del asiento es clave para la ergonomía y la salud del conductor.', NULL),
('cap-61060f68342c', 'Accionar la luz de emergencia es una medida que se toma cuando ya ha ocurrido una incidencia o para señalizar una parada, no es una acción preventiva para evitar un incendio. Revisar los frenos, los extintores y el buen estado general de la mecánica son todas acciones que se realizan de forma anticipada para prevenir posibles riesgos, incluyendo el de incendio.', NULL),
('cap-611321d8707a', 'El calderín es un componente del sistema de frenos de aire, donde se almacena el aire comprimido. El retardador hidráulico, en cambio, funciona con aceite que circula entre un estátor fijo y un rotor, generando resistencia para frenar el vehículo. Por lo tanto, el calderín no tiene ninguna función en el sistema de retardador hidráulico. El aceite es el fluido de trabajo del retardador, y el estátor y el rotor son sus componentes principales.', NULL),
('cap-611f3df21905', 'Los vehículos pesados tienen una siniestralidad menor por vehículo-kilómetro que el total de vehículos. Esto se debe a que sus conductores son profesionales, están más formados y tienen más experiencia. Además, estos vehículos están sujetos a revisiones más estrictas y a normativas de tiempos de conducción y descanso que reducen la fatiga. La idea de que la siniestralidad es mayor es un error común, pero los datos demuestran lo contrario.', NULL),
('cap-614723b6f908', 'Los motores diésel de inyección indirecta tienen una cámara de combustión auxiliar donde se inicia la combustión antes de pasar a la cámara principal. Este proceso genera más pérdidas de calor y una combustión menos eficiente, lo que se traduce en un mayor consumo de combustible para producir la misma potencia. Por el contrario, los motores de inyección directa introducen el combustible directamente en la cámara principal, optimizando la combustión y reduciendo el consumo. La afirmación de que el consumo es menor cuanto mayor sea el número de revoluciones es incorrecta, ya que el consumo específico no disminuye indefinidamente con el aumento de las revoluciones.', NULL),
('cap-614dc0ff24d9', 'Los elementos de protección como gafas, guantes y botas están diseñados para proteger directamente contra impactos y abrasiones. Por eso, no usarlos aumenta el riesgo de golpes con herramientas o de que objetos pequeños impacten en ojos, manos o pies. La caída de objetos al manipularlos es un riesgo diferente, relacionado con la sujeción, no con la protección personal.', NULL),
('cap-6164333b3d20', 'El cuaderno de ruta de la autorización CEMT sirve para registrar todos los movimientos del vehículo, tanto si transporta mercancía como si circula sin ella. Es fundamental para el control de los tráficos internacionales y para verificar el cumplimiento de las condiciones de la autorización. Registrar solo los recorridos con carga o solo los recorridos en vacío no daría una imagen completa de la actividad del transporte.', NULL),
('cap-6169db8ede06', 'Los vehículos que no pueden superar los 40 km/h están exentos del uso del tacógrafo, ya que su baja velocidad los excluye de la normativa general de tiempos de conducción y descanso. Esta exención se aplica porque no se consideran vehículos de transporte de larga distancia. La exención para autobuses de menos de 3.500 kg de MMA es incorrecta, ya que la masa no es el criterio principal para la exención en este tipo de vehículos.', 'Reglamento Comunitario;RD (CE) 561/2006;640/2007 Art. 3;Art. 2'),
('cap-618f0fecd8a7', 'La afirmación de que los aspirantes deben superar un examen en un plazo no superior a tres meses desde la finalización del curso es falsa. El RD 1032/2007 Art. 15 no establece ningún plazo máximo para presentarse al examen una vez terminado el curso de formación. Lo que sí indica la normativa es que deben convocarse exámenes al menos seis veces al año, con un mes de antelación y un plazo de inscripción no inferior a quince días.', 'RD 1032/2007 Art. 15'),
('cap-61a7a9ffdea8', 'La resistencia a la rodadura se produce principalmente por la deformación del neumático al girar. Cuanto más se flexiona el neumático, más energía se disipa en forma de calor, lo que aumenta la resistencia. Por lo tanto, un mayor trabajo de flexión implica una mayor resistencia a la rodadura. La fricción en el rodamiento de la rueda es un factor menor en comparación con la deformación del neumático.', NULL),
('cap-61d5755696ae', 'Circular con una presión de inflado superior a la recomendada por el fabricante es una medida equivocada porque, aunque podría reducir ligeramente la resistencia a la rodadura, compromete la seguridad y el agarre del vehículo. Una presión excesiva disminuye la superficie de contacto del neumático con la carretera, lo que afecta negativamente la estabilidad, la frenada y la dirección. Además, provoca un desgaste irregular del neumático por el centro, acortando su vida útil. Aprovechar la inercia del vehículo, observar las revoluciones para cambiar de marcha y dejar de acelerar con antelación son, por el contrario, técnicas de conducción eficiente que sí contribuyen al ahorro de carburante.', NULL),
('cap-61de61b7b37d', 'La marca es una herramienta clave para que los clientes identifiquen y distingan los servicios de una empresa de los de sus competidores. Ayuda a construir una imagen y una reputación únicas en el mercado. Decir que representa una promesa de insatisfacción es incorrecto, ya que el objetivo de una marca es generar confianza y expectativas positivas.', NULL),
('cap-61f7cdc79a43', 'Cuando una sociedad anónima no se inscribe en el Registro Mercantil en el plazo de un año desde su constitución, pasa a ser una sociedad irregular. Esto significa que, aunque no esté inscrita, si ha iniciado operaciones, se le aplicarán las normas de la sociedad colectiva o de la sociedad civil, según corresponda, tal como establece el RD Legislativo 1/2010 Art. 39. No es que la sociedad sea nula o inexistente, sino que su régimen jurídico cambia por no haber completado el proceso de inscripción.', 'RD Legislativo 1/2010 Art. 39'),
('cap-62107d3b7207', 'La fatiga aparece con mayor facilidad en tareas monótonas y repetitivas que se prolongan en el tiempo, ya que el cerebro se acostumbra a los estímulos y reduce su nivel de alerta. Aunque una actividad dure más de cinco horas, si no es repetitiva, la fatiga puede tardar más en aparecer. La falta de repetición de estímulos o la no necesidad de atención constante no favorecen la fatiga, sino que la reducen al permitir cambios o descansos mentales.', NULL),
('cap-62144b248239', 'En las sociedades laborales, la Ley 44/2015 Art. 1.2 establece que al menos la mayoría del capital social debe ser propiedad de los trabajadores que prestan servicios en la empresa de forma personal y directa. Esto asegura que el control y la propiedad de la empresa recaigan principalmente en sus empleados. Las cooperativas de trabajo asociado y las cooperativas de transportistas tienen una estructura diferente, donde el capital no tiene por qué pertenecer mayoritariamente a los trabajadores de la empresa en ese porcentaje específico. Las sociedades de garantía recíproca son entidades financieras que facilitan el acceso al crédito a pymes, no sociedades donde el capital pertenece a los trabajadores.', 'Ley 44/2015 Art. 1.2'),
('cap-6224c19fbbe7', 'Ante la caída de carga, nunca debes abandonar la zona inmediatamente. Tu prioridad es señalizar el peligro y avisar a los demás usuarios para evitar accidentes. Además, debes contactar con los servicios de auxilio para que retiren la carga de forma segura. Abandonar la zona es una irresponsabilidad que puede provocar un accidente grave.', NULL),
('cap-623bc0c39d03', 'Al iniciar la frenada, se necesita la máxima fuerza para detener el vehículo. A medida que la velocidad disminuye, la inercia es menor y se requiere menos presión para evitar el bloqueo de las ruedas y mantener el control. Una presión suave y mantenida no es eficaz para una frenada de emergencia. Presionar suave al principio y aumentar la presión progresivamente es incorrecto porque se perdería eficacia al inicio de la frenada.', NULL),
('cap-62402ba0107d', 'Un cambio de apoyo se produce cuando el vehículo transfiere su peso de las ruedas de un lado a las del otro, lo cual es habitual en curvas enlazadas. Este movimiento es clave para entender cómo se comporta el camión en giros sucesivos. No se refiere a la inclinación máxima ni a un apoyo prolongado en una curva, sino al balanceo lateral. Tampoco es un cambio de apoyo entre los ejes delantero y trasero, ya que eso se relaciona más con la transferencia de masas en aceleración o frenada.', NULL),
('cap-62490b091f5b', 'Los costes directos de un accidente son aquellos que se pueden cuantificar económicamente de forma inmediata. Los daños a la propiedad, como los desperfectos en el vehículo o la infraestructura, son claramente cuantificables. Los gastos médicos derivados de la atención a los heridos también son un coste directo. Igualmente, los gastos administrativos, como los de gestión de seguros o peritajes, son costes directos asociados al suceso.', NULL),
('cap-627df748c825', 'El Reglamento Comunitario (CE) 561/2006 Art. 4.k define el "tiempo diario de conducción" exactamente como el tiempo acumulado total de conducción entre el final de un período de descanso diario y el principio del siguiente período de descanso diario. Esta es la definición literal que establece la normativa para este concepto. El "tiempo semanal de conducción" se refiere al total de horas conducidas en una semana, no entre descansos diarios.', 'Reglamento Comunitario (CE) 561/2006 Art. 4.k'),
('cap-62a7a701848f', 'La energía cinética de un vehículo en movimiento se puede transformar en energía de avance sin consumir combustible si dejas de acelerar, aprovechando la inercia. Esto es lo que se conoce como conducción por inercia o a vela, y es una técnica de conducción eficiente. La energía asociada al movimiento es mayor en vehículos pesados que en ligeros, no al revés. No hay riesgo de accidente por calentamiento de frenos al aprovechar la inercia, ya que precisamente se reduce el uso del freno de servicio.', NULL),
('cap-62ccb29e561b', 'El conductor es el responsable directo de las infracciones de tráfico que se cometan mientras está al volante, ya que es quien maneja el vehículo y debe cumplir las normas de circulación. Esto está recogido en el RD Legislativo 6/2015 Art. 82.1. Ni el empresario, ni el cargador, ni el consignatario tienen control sobre la conducción en el momento de la infracción.', 'RD Legislativo 6/2015 Art. 82.1'),
('cap-62f1b06e08fe', 'La histéresis es el fenómeno físico que permite al neumático agarrarse a la carretera. Se produce por la deformación y recuperación constante de la goma al rodar, lo que genera calor y fricción. Esta fricción es la que proporciona la adherencia necesaria para la tracción y el frenado. La opción que habla de que el neumático supera su límite de presión es incorrecta, ya que la histéresis no tiene relación con la sobrepresión.', NULL),
('cap-6302c1044062', 'La normativa comunitaria sobre transporte de animales vivos se aplica a todos los animales vertebrados vivos, sin excepciones por especie. El Reglamento Comunitario (CE) 1/2005 Art. 1.1 lo deja claro. No se limita a ciertas especies como equina, bovina o porcina. Tampoco se aplica a transportes que no sean por actividad económica o a los que van o vienen de clínicas veterinarias por consejo de un veterinario, ya que estos están expresamente excluidos del ámbito de aplicación general.', 'Reglamento Comunitario (CE) 1/2005 Art. 1.1'),
('cap-63906359286d', 'El deslizamiento de la rueda se produce cuando la fuerza aplicada a la rueda es mayor que la adherencia disponible con la calzada. Esto puede ocurrir al acelerar, si la fuerza del motor hace girar la rueda más rápido de lo que avanza el camión, o al frenar, si la fuerza de frenado hace que la rueda gire más despacio o se bloquee. La opción que indica que solo ocurre por frenada o solo por aceleración es incorrecta porque ambas situaciones pueden provocar una pérdida de adherencia. Pensar que ocurre principalmente en rectas es un error, ya que las curvas, con sus fuerzas laterales, pueden incluso agravar el deslizamiento.', NULL),
('cap-639c0e9e6e9f', 'Una presión incorrecta en los neumáticos, ya sea por exceso o por defecto, aumenta la resistencia a la rodadura del vehículo. Esta mayor resistencia obliga al motor a trabajar más para mantener la velocidad, lo que se traduce directamente en un mayor consumo de combustible. Por lo tanto, mantener la presión adecuada es clave para la eficiencia. Decir que no influye en el consumo es incorrecto, ya que la resistencia a la rodadura es un factor directo.', NULL),
('cap-63b00ef58226', 'El par motor es la fuerza que hace girar el cigüeñal y se genera por la expansión de los gases de la combustión dentro de los cilindros. Esta expansión empuja los pistones, que a su vez mueven el cigüeñal. La compresión de la mezcla es una fase previa, no la que genera el par motor. La apertura y cierre de válvulas controla el flujo de gases, pero no produce directamente el par motor.', NULL),
('cap-63b502c076bc', 'Una alimentación inadecuada, ya sea por falta de nutrientes esenciales o por un desequilibrio en la dieta, puede afectar el nivel de azúcar en sangre y la presión arterial, lo que fácilmente provoca mareos y desvanecimientos. No es solo la cantidad de comida lo que importa, sino también la calidad y el equilibrio de los alimentos que se ingieren. Afirmar que solo puede producir mareos o desvanecimientos por separado es incorrecto, ya que ambos síntomas pueden presentarse como consecuencia de una mala alimentación.', NULL),
('cap-63c52f151523', 'El efecto fading ocurre por un sobrecalentamiento de los frenos debido a un uso excesivo o continuado, lo que reduce su eficacia. Esto es un mal uso del freno de servicio, ya que se debería usar el freno motor o el ralentizador para evitarlo. Las otras opciones se refieren a problemas con los neumáticos, que no tienen relación con el efecto fading.', NULL),
('cap-63e7b0b6d8c8', 'Debes evacuar el vehículo inmediatamente si se ha incendiado o hay riesgo de incendio, ya que tu seguridad es lo primero y el fuego puede propagarse rápidamente. Permanecer dentro te expone a quemaduras, inhalación de humo y otros peligros graves. Las tormentas, la lluvia o los relámpagos no justifican evacuar el vehículo, ya que el habitáculo ofrece protección frente a estos fenómenos meteorológicos.', NULL)
) as v(id, explicacion, norma)
where preguntas.id = v.id::text;
